// Helper : récupérer un effet par ID
function getEffectById(id) {
    return ALL_EFFECTS.find(e => e.id === id) || null;
}

// Helper : compter les effets par catégorie
function countByCategory(catId) {
    if (catId === 'all') return ALL_EFFECTS.length;
    return ALL_EFFECTS.filter(e => e.cat === catId).length;
}

